#!/usr/bin/env python3
"""Render truthful source/test evidence as PNGs accepted by the TAC portal.

These are rendered evidence documents, not screenshots of a running application.
Run with a Python installation providing Pillow. No network or production data.
"""
import hashlib
import json
from pathlib import Path
import re
import subprocess
import textwrap
from PIL import Image, ImageDraw, ImageFont

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
REQS = json.loads((HERE / 'requirements.json').read_text())
OAUTH = 'crates/overlook-provider/src/gmail/oauth.rs'
SIGNIN = 'crates/overlook-app/src/google_signin.rs'
VAULT = 'crates/overlook-app/src/credentials.rs'
API = 'crates/overlook-provider/src/gmail/api.rs'
PROVIDERS = 'crates/overlook-app/src/providers.rs'
UI = 'crates/overlook-app/src/ui/mod.rs'
