R = {}

def add(ids, applicable, explanation, refs, validation='Source review; see the referenced code excerpts.'):
    for ident in ids.split():
        R[ident] = dict(applicable=applicable, explanation=explanation, refs=refs, validation=validation)

AUTH = ('Google Account authentication is performed in the system browser. Overlook is a native Linux public OAuth client and does not operate an authentication server or collect Google passwords. IMAP/POP3/SMTP authentication is performed by each user-selected mail provider. The local OS user controls access to the installed application and its profile.')
add('1.1.1', True, AUTH + ' Brute-force prevention and MFA for Google accounts are provided by Google; there is no proprietary Overlook password login to brute-force. The local callback additionally requires an unpredictable state and PKCE.', [(SIGNIN,'pub fn start(',20),(OAUTH,'pub fn random()',12)], 'Authorization/PKCE and forged-callback regression tests passed. Provider-side brute-force/MFA behavior was not independently penetration-tested.')
add('1.1.2', False, AUTH + ' Overlook does not issue initial passwords, activation codes, or password-reset codes. This control is not applicable to an Overlook-managed password lifecycle.', [(SIGNIN,'pub fn start(',18),(OAUTH,'pub fn exchange_code(',9)])
add('1.1.3', True, 'Google passwords are never received. OAuth access/refresh tokens and optional IMAP/POP3/SMTP passwords are stored through oo7 in the OS Secret Service or encrypted Secret Portal-backed keyring. A mail client must retrieve server passwords to authenticate, so one-way password-verifier hashing is not the applicable storage model. Keyring failures are surfaced, with no application plaintext fallback. Encryption strength and unlock protection depend on the selected OS keyring. The SQLite mail cache is not application-encrypted.', [(VAULT,'pub fn save_secret(',8),(VAULT,'pub fn save_tokens(',6),(PROVIDERS,'fn stored_passwords(',20)])
add('1.2.1', False, 'Overlook exposes no public login or administrative interface and ships no default mail credentials. The fictional Sample provider is local demonstration data, not an account on a server. The only HTTP listener is a temporary IPv4 loopback OAuth callback requiring per-attempt state and PKCE; it has no password login.', [(SIGNIN,'pub fn start(',20),(MAIN,'pub fn seed_sample_account(',11)])
add('1.3.1 1.3.2 1.3.3 1.3.4', False, AUTH + ' Overlook has no SMS/email/telephone OTP or proprietary out-of-band verifier. OAuth uses the system browser and loopback callback, not the deprecated manual OOB flow. As supplemental native-flow protections, each attempt uses fresh state and PKCE, has a 600-second timeout, and consumes one validated callback.', [(SIGNIN,'pub const SIGN_IN_TIMEOUT',1),(SIGNIN,'if started.elapsed()',13),(OAUTH,'pub fn random()',12)], 'PKCE RFC 7636 vector, state validation, duplicate-parameter and wrong-host callback tests passed. No proprietary OOB verifier exists to test.')
add('2.1.1', True, 'Google access tokens are sent in Authorization: Bearer headers. Token exchange, refresh, and revocation secrets are form POST bodies over HTTPS, never URL query parameters. The native loopback URL carries a one-time authorization code and state, not an access or refresh token; responses use no-store and no-referrer. Overlook exposes no public API. Attached evidence is native source/regression evidence, not a web DAST scan.', [(API,'pub fn get_url(',10),(OAUTH,'fn post_form(',8),(OAUTH,'pub fn revoke(',10)], 'Source review plus OAuth encoding/callback tests and credential logging regression passed; TAC to confirm native-app DAST coverage.')
add('2.2.1', True, 'Remove account now disables the shared Gmail client, drains an in-flight request, revokes the Google grant by HTTPS POST, clears in-memory tokens, then deletes the OS keyring entries and local account records. Cloned providers cannot refresh or persist credentials after disconnect. Failed revocation or keyring deletion is reported as incomplete removal and retains retry information; Gmail removal requires connectivity. Revocation affects this user’s grant for the Google project across devices/scopes. Legacy mail-provider passwords are removed locally, not changed at their issuer.', [(API,'fn disconnect_with(',12),(UI,'pub(crate) fn remove_account(',24),(OAUTH,'pub fn revoke(',10)], 'Disconnect failure/retry/cloned-client regression passed. Live Google grant revocation and OS-keyring removal still require an assessor/test-account integration check; these changes are an unreleased candidate.')
add('2.2.2', False, 'Overlook does not provide an account-password change/reset service or issue cross-device sessions. Google and the selected mail provider own password changes and their session policies. Updating a saved IMAP password changes the local credential, not the provider password. Rejected Google refresh credentials map to SignInRequired. App disconnect explicitly revokes the Google grant; no claim is made that Overlook controls Google’s other sessions.', [(API,'match oauth::refresh(',13),(PROVIDERS,'pub fn providers_for(',14)])
add('2.2.3', False, 'Overlook does not issue non-revocable stateless session tokens. It consumes Google-issued, revocable OAuth tokens, honors expires_in, and treats access tokens as expired 60 seconds early. The default expiry when omitted is one hour. Refresh tokens are stored in the keyring and explicitly revoked on disconnect. Returned ID tokens are not used to authorize local users or API requests.', [(OAUTH,'let expires_in =',16),(OAUTH,'pub fn is_expired(',4)])
add('2.3.1 2.3.2', False, 'No Overlook cookie-based authentication or web session exists. API requests use bearer headers and the loopback completion page sets no cookies. The user’s system browser may retain Google’s own sign-in cookies; Overlook does not create, read, or administer them. The isolated mail renderer has no authenticated browser session. A cookie-attribute DAST finding against a hosted Overlook application is therefore not applicable.', [(API,'pub fn get_url(',10),(SIGNIN,'let body = completion_page',15)])
add('2.3.3', True, 'Google API access uses dynamically issued short-lived OAuth bearer tokens and refresh tokens. The Desktop OAuth client identifier and its non-confidential client-secret field do not independently authorize user data. IMAP/POP3/SMTP support uses the provider’s password/app-password mechanism as a legacy-protocol exception; those secrets are keyring-protected and transmitted only after remote TLS setup.', [(OAUTH,'pub fn exchange_code(',9),(API,'fn access_token(',25),(SMTP,'fn connect(',24)])
add('2.3.4', False, 'Overlook does not mint or accept client-supplied JWT/stateless session tokens as a local authorization mechanism. Google opaque bearer tokens are sent only to Google for provider-side validation. The application does not decode or trust a JWT payload or select signature algorithms. Unsupported/invalid credentials fail through the API error path. No app-managed stateless-token signer or verifier exists for web DAST.', [(API,'fn with_retry(',30)])
add('2.4.1', True, 'Mail, calendar, and contact operations require an authenticated provider. Google calls attach a valid token, refresh on expiry, and stop on invalid grants/401. Google enforces scope/resource permissions. Missing keyring credentials prevent construction of an authenticated provider. Local settings and offline cached mail belong to the OS user; Overlook has no separate application password or financial transaction service.', [(PROVIDERS,'pub fn providers_for(',19),(API,'fn access_token(',25)])
ACCESS = ('Overlook is a single-OS-user desktop client, not a multi-tenant server. Google is the trusted service enforcing token scopes, account ownership, calendar sharing, and contacts permissions. Gmail requests are scoped to users/me using that account’s bearer token. Local profile data is owned by the OS user; editing a local preference cannot grant Google permissions. Selected Gmail, calendar, contacts and Gmail-settings scopes support the implemented mail, calendar, contact editing and settings features; no Drive/admin/domain-wide-delegation scope is requested.')
