add('6.7.1', True, 'No Overlook server-side secret store or backend exists. OAuth access/refresh tokens and mail-provider passwords are stored using oo7 in OS Secret Service (or encrypted Secret Portal-backed storage in a sandbox), scoped by application/account/kind. Configuration and SQLite do not store these credentials. Keyring failures are surfaced without plaintext fallback. The desktop OAuth client JSON contains a public-client identifier and non-confidential client-secret field; it is not a substitute for user authorization.', [(VAULT,'const APPLICATION:',10),(VAULT,'pub fn save_secret(',8),(VAULT,'pub fn save_tokens(',13),(PROVIDERS,'fn stored_passwords(',19)])

assert set(R) == {q['id'] for q in REQS}

def font(name, size):
    path = subprocess.check_output(['fc-match','-f','%{file}',name],text=True)
    return ImageFont.truetype(path,size)

F = {k:font(n,s) for k,n,s in [('title','sans:bold',40),('h','sans:bold',26),('body','sans',24),('small','sans',20),('code','monospace',19)]}

def source(path, anchor, count):
    p = ROOT / path
    content = p.read_text()
    lines = content.splitlines()
    start = next((i for i,v in enumerate(lines) if anchor in v),None)
    if start is None: raise ValueError(f'Missing evidence anchor: {path}: {anchor}')
    return {'path':path,'line':start+1,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'lines':lines[start:start+count]}

def render(q, item, manifest):
    canvas = Image.new('RGB',(1600,10000),'#ffffff'); d = ImageDraw.Draw(canvas); y=50
    def text(value, kind='body', color='#172b35', indent=0):
        nonlocal y
        f=F[kind]; width=1472-indent
        for para in str(value).split('\n'):
            chunks = [para] if kind=='code' else para.split(' ')
            if kind=='code':
                limit=int(width / d.textlength('M',font=f)); lines=textwrap.wrap(para,limit,replace_whitespace=False,drop_whitespace=False) or ['']
            else:
                lines=[]; line=''
                for word in chunks:
                    nxt=(line+' '+word).strip()
                    if d.textlength(nxt,font=f)>width and line: lines.append(line);line=word
                    else: line=nxt
                lines.append(line)
            for line in lines:
                d.text((64+indent,y),line,font=f,fill=color);y+=int(f.size*1.45)
    def heading(label):
        nonlocal y
        y+=20;text(label,'h');y+=8
    text(f'OVERLOOK  |  CASA {q["id"]}','title'); y+=7
    text('Rendered source and test evidence • 22 October 2026','small','#47626d')
    text('Desktop application • 1.5.5 assessment candidate • unreleased local changes','small','#47626d')
    text('Source baseline: '+manifest['base_commit'][:12]+'  |  source manifest: '+manifest['digest'][:20],'small','#47626d')
    y+=18;d.line((64,y,1536,y),fill='#cbd8d8',width=2);y+=18
    text(q['requirement'].rstrip(' *'),'h')
    heading('Applicability: '+('Yes — implementation evidence' if item['applicable'] else 'No — architecture rationale'))
    text(item['explanation'])
    heading('Validation and limits');text(item['validation'])
    for src in item['sources']:
        heading(src['path']+':'+str(src['line']))
        text('SHA-256: '+src['sha256'][:32]+'…','small','#47626d')
        for i,line in enumerate(src['lines'],src['line']): text(f'{i:4}  {line}','code')
    y+=25;d.line((64,y,1536,y),fill='#cbd8d8',width=2);y+=17
    text('Evidence document, not a live application screenshot or a certificate of compliance.','small','#47626d')
    text('Source excerpts are exact; code indentation may wrap. Assessor determines acceptance.','small','#47626d')
    assert y<9900
    canvas.crop((0,0,1600,y+45)).save(HERE/'evidence'/f'casa-{q["id"]}.png',optimize=True)

def main():
    audit=json.loads((HERE/'logs/dependencies-after.json').read_text())
    warnings=[x for v in audit.get('warnings',{}).values() for x in v]
    summary=['Scan: cargo-audit 0.22.2 / RustSec / 2026-10-22',f'Known vulnerabilities: {audit["vulnerabilities"]["count"]}',f'Maintenance warnings: {len(warnings)} (not suppressed)',f'Database: {audit["database"]["last-commit"]}','', 'Warnings:']
    summary += [x['package']['name']+' '+x['package']['version']+' — '+x['advisory']['id']+' — '+x['advisory']['title'] for x in warnings]
    (HERE/'logs/dependency-summary.txt').write_text('\n'.join(summary)+'\n')
    base=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
    paths=sorted({ref[0] for item in R.values() for ref in item['refs']}|{'Cargo.lock','Cargo.toml','crates/overlook-app/Cargo.toml'})
    hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in paths}
    manifest={'base_commit':base,'date':'2026-10-22','version':'1.5.5','state':'Unreleased local assessment candidate','files':hashes}
    manifest['digest']=hashlib.sha256(json.dumps(hashes,sort_keys=True).encode()).hexdigest()
    (HERE/'source-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    responses=[]; md=['# Overlook CASA control evidence','', 'Scope: native Linux desktop app, v1.5.5 candidate based on '+base+'. The evidence includes unreleased local security fixes. This is a developer evidence package; TAC determines control acceptance. No real user mailbox, tokens, passwords, or production credential files were used.','', 'The PNGs are rendered source/test documents, not screenshots of a live Google login. Source hashes and line references identify the reviewed material.','']
    for q in REQS:
        item=R[q['id']];item['sources']=[source(*ref) for ref in item['refs']]
        comment='Overlook native Linux desktop app. '+item['explanation']+' Evidence: source/test document for unreleased v1.5.5 assessment candidate; details and limits in attachment.'
        assert len(comment)<=1500,(q['id'],len(comment))
        entry={'id':q['id'],'applicable':'1' if item['applicable'] else '0','comment':comment,'evidence':str(HERE/'evidence'/f'casa-{q["id"]}.png'),'validation':item['validation']}
        responses.append(entry);render(q,item,manifest)
        md += ['## '+q['id']+' '+q['requirement'].rstrip(' *'),'','Applicable: '+('Yes' if item['applicable'] else 'No'),'',item['explanation'],'',item['validation'],'']
        md += ['- `'+s['path']+':'+str(s['line'])+'`' for s in item['sources']]+['','[Evidence image](evidence/casa-'+q['id']+'.png)','']
    (HERE/'responses.json').write_text(json.dumps(responses,indent=2,ensure_ascii=False)+'\n')
    (HERE/'control-matrix.md').write_text('\n'.join(md))
    print(f'Rendered {len(responses)} evidence images; {sum(x["applicable"]=="1" for x in responses)} applicable, {sum(x["applicable"]=="0" for x in responses)} not applicable.')

if __name__=='__main__': main()
